<script setup lang="ts">
import { computed, nextTick, ref } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import axios from 'axios';
import DashboardLayout from '../layouts/DashboardLayout.vue';
import FinanceDashboard from '../components/FinanceDashboard.vue';
import type { School, SchoolDashboard } from '../types';
const props=defineProps<{page:string;financePage:string;title:string;schools:School[];selectedSchool:School|null;dashboard:SchoolDashboard|null;baseUrl:string;fields:{key:string;type:string;label:string}[];rows:any;options:Record<string,any[]>;filters:Record<string,any>;reportRows:Record<string,any>[];metrics:Record<string,any>;summary:Record<string,any>;flash:{success?:string}}>();
const tabs=[['dashboard','Overview'],['categories','Fee categories'],['structures','Fee structures'],['assignments','Assignments'],['generate','Generate invoices'],['invoices','Invoices'],['payments','Payments & receipts'],['discounts','Concessions'],['late-fees','Late fees'],['refunds','Refunds'],['expenses','Expenses'],['expense-categories','Expense categories'],['defaulters','Defaulters'],['statements','Statements'],['reports','Reports'],['audit','Audit']];
const editable=computed(()=>['categories','structures','discounts','late-fees','expense-categories'].includes(props.financePage));
const show=ref(false), editId=ref<number|null>(null), formPanel=ref<HTMLElement|null>(null);
const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Karachi'});
const defaults:Record<string,any>={active:true,auto_assign:true,issue:true,late_fee_exempt:false,frequency:'monthly',calculation:'fixed',kind:'custom',method:'cash',grace_days:0,paid_on:today,spent_on:today,refunded_on:today,issued_on:today,due_on:today,period:today.slice(0,7)+'-01'};
const form=useForm<Record<string,any>>({...Object.fromEntries(props.fields.map(f=>[f.key,defaults[f.key]??''])),idempotency_key:'',allocations:[]});
const filter=useForm<Record<string,any>>({q:'',academic_session_id:'',academic_class_id:'',section_id:'',student_id:'',fee_category_id:'',expense_category_id:'',from:'',to:'',due_from:'',due_to:'',method:'',status:'',report_type:'invoices',...props.filters});
const confirmation=ref<{id:number;action:string;resource:string}|null>(null);
const actionForm=useForm<Record<string,any>>({confirm:true,reason:'',policy_id:'',preview_amount_minor:0,invoice_id:'',amount:''});
const preview=ref<number|null>(null), previewBusy=ref(false), previewError=ref('');
const settings=useForm({currency:props.metrics.currency});
const money=(n:number)=>new Intl.NumberFormat('en-PK',{style:'currency',minimumFractionDigits:2,maximumFractionDigits:2,currency:props.metrics.currency}).format(Number(n)/100);
const decimal=(n:number)=> (Number(n)/100).toFixed(2);
function open(row?:any){
    editId.value=row?.id??null; form.clearErrors();
    form.reset();
    for(const f of props.fields) form[f.key]=row?.[f.key]??defaults[f.key]??'';
    if(row){if(row.amount_minor!==undefined)form.amount=decimal(row.amount_minor); if(row.cap_minor!==undefined)form.cap=decimal(row.cap_minor); if(row.value!==undefined)form.value=decimal(row.value);}
    form.idempotency_key=crypto.randomUUID(); form.allocations=[];show.value=true;nextTick(()=>{formPanel.value?.scrollIntoView({behavior:'smooth',block:'start'});formPanel.value?.querySelector<HTMLInputElement>('input,select')?.focus();});
}
function save(){const options={preserveScroll:true,onSuccess:()=>{show.value=false;}};if(editId.value)form.put(`${props.baseUrl}/${props.financePage}/${editId.value}`,options);else form.post(`${props.baseUrl}/${props.financePage}`,options);}
function remove(row:any){if(window.confirm('Delete this unused configuration? Referenced financial history is protected.'))router.delete(`${props.baseUrl}/${props.financePage}/${row.id}`,{preserveScroll:true});}
function begin(row:any,resource:string,action:string){confirmation.value={id:row.id,resource,action};actionForm.reset();actionForm.clearErrors();preview.value=null;previewError.value='';nextTick(()=>document.getElementById('finance-confirm')?.focus());}
function perform(){if(!confirmation.value)return;actionForm.post(`${props.baseUrl}/${confirmation.value.resource}/${confirmation.value.id}/${confirmation.value.action}`,{preserveScroll:true,onSuccess:()=>{confirmation.value=null;}});}
async function previewPenalty(){if(!confirmation.value)return;previewBusy.value=true;previewError.value='';try{const r=await axios.post(`${props.baseUrl}/invoices/${confirmation.value.id}/preview-penalty`,{policy_id:actionForm.policy_id});preview.value=r.data.amount_minor;actionForm.preview_amount_minor=r.data.amount_minor;}catch(e:any){previewError.value=e.response?.data?.message??'Unable to preview penalty.';}finally{previewBusy.value=false;}}
function opts(f:{key:string;type:string}){let rows=props.options[f.type]??[];if(f.key==='section_id'&&form.academic_class_id)rows=rows.filter(o=>o.class_id===Number(form.academic_class_id));return rows;}
function selectType(t:string){return t.includes('|')||!!props.options[t];}
const paymentInvoices=computed(()=> (props.options.invoices??[]).filter(i=>i.student_id===Number(form.student_id)));
function apply(){router.get(`${props.baseUrl}/${props.financePage}`,Object.fromEntries(Object.entries(filter.data()).filter(([key])=>visibleFilters.value.includes(key)||key==='report_type')),{preserveState:true,replace:true});}
const exportHref=computed(()=>`${props.baseUrl}/reports/export?${new URLSearchParams(Object.fromEntries(Object.entries(props.filters).filter(([,v])=>v!==null&&v!==''))).toString()}`);
const visibleFilters=computed(()=>{
 const page=props.financePage;
 if(page==='reports'){
  const type=filter.report_type||'invoices';
  if(['expenses','expense-categories'].includes(type))return ['from','to','method','expense_category_id'];
  if(type==='refunds')return ['from','to','student_id'];
  return ['q','academic_session_id','academic_class_id','section_id','student_id','fee_category_id','from','to','due_from','due_to',...(['payments','daily','monthly','class','category','method'].includes(type)?['method']:['status'])];
 }
 return ({structures:['q','academic_session_id','academic_class_id','section_id','fee_category_id'],assignments:['academic_session_id','academic_class_id','section_id','student_id','fee_category_id'],discounts:['q','academic_session_id','student_id','fee_category_id'],invoices:['q','academic_session_id','academic_class_id','section_id','student_id','fee_category_id','from','to','due_from','due_to','status'],defaulters:['academic_session_id','academic_class_id','section_id','student_id','due_from','due_to'],statements:['student_id','from','to'],payments:['student_id','from','to','method'],refunds:['student_id','from','to'],expenses:['expense_category_id','from','to','method'],categories:['q'],'expense-categories':['q'],'late-fees':['q']} as Record<string,string[]>)[page]??[];
});
const reportColumns=computed(()=>Object.keys(props.reportRows[0]??{}));
function print(){window.print();}
function rowLabel(row:any){return row.number??row.name??(props.financePage==='audit'?row.operation:`#${row.id}`);}
function rowDetail(row:any){return row.snapshot?.student_name??row.payee??(row.student_id?`Student #${row.student_id}`:row.entity_type??row.frequency??'School configuration');}
function displayStatus(row:any){if(row.status==='issued'){if(Number(row.outstanding_minor)===0)return 'paid';if(row.due_on<today)return 'overdue';if(Number(row.paid_minor)>0)return 'partially paid';}return row.status??(row.active===false?'inactive':'active');}
</script>
<template>
<Head :title="title"/>
<DashboardLayout :page="page" :title="title" :schools="schools" :selected-school="selectedSchool" :dashboard="dashboard">
<div class="page-heading"><div><h1>{{ title }}</h1><p>School finance · local development preview · {{ metrics.currency }}</p></div><button v-if="fields.length" class="academic-button no-print" @click="open()">{{ editable?'Create record':financePage==='generate'?'Generate invoices':financePage==='assignments'?'Assign fees':financePage==='refunds'?'Request refund':'Record '+(financePage==='payments'?'payment':'expense') }}</button></div>
<nav class="finance-tabs no-print" aria-label="School finance"><Link v-for="tab in tabs" :key="tab[0]" :href="`${baseUrl}/${tab[0]}`" :class="{active:financePage===tab[0]}" :aria-current="financePage===tab[0]?'page':undefined">{{ tab[1] }}</Link></nav>
<p v-if="flash.success" class="success-message" role="status">{{ flash.success }}</p>
<p class="finance-note">Manual records only. These reports describe fee billing, collections, refunds and expenses; they are not audited financial statements or a general ledger.</p>
<FinanceDashboard v-if="financePage==='dashboard'" :data="metrics" :base-url="baseUrl"/>
<form v-if="financePage==='dashboard'" class="panel finance-currency no-print" @submit.prevent="settings.post(baseUrl+'/settings')"><label for="currency">School currency (configure before creating records)</label><select id="currency" v-model="settings.currency"><option v-for="c in ['PKR','USD','GBP','EUR','AED','SAR']" :key="c">{{ c }}</option></select><button class="secondary-button" :disabled="settings.processing">Save currency</button><p v-for="e in settings.errors" :key="e" class="field-error">{{ e }}</p></form>

<section v-if="show" ref="formPanel" class="panel finance-form no-print"><div class="panel-heading"><h2>{{ editId?'Edit':'New' }} {{ title }}</h2><button type="button" class="secondary-button" @click="show=false">Close</button></div><form @submit.prevent="save" novalidate>
<p v-if="financePage==='assignments'" class="finance-note">Leave student blank for the eligible class/section roster. Assign a section override instead of its class default. Repeating the same assignment is safe.</p><p v-if="financePage==='generate'" class="finance-note">Bills previously assigned fees at their monthly, quarterly, annual or one-time schedule. The period is normalized to its first day. Existing monthly invoices are returned unchanged.</p><p v-if="financePage==='discounts'" class="finance-note">Fixed values are currency amounts; percentage values are 0–100. The largest eligible concession per item wins; concessions do not stack. Existing invoices stay unchanged.</p><p v-if="financePage==='refunds'" class="finance-note">Choose the invoice allocation to refund, or leave invoice blank to refund unallocated credit. A request reserves eligibility; post it only after manually recording the refund.</p>
<div class="academic-form-grid"><div v-for="f in fields" :key="f.key" class="form-field"><label :for="'fin-'+f.key">{{ f.label }}{{ ['amount','adjusted_amount','cap'].includes(f.key)?' ('+metrics.currency+')':'' }}</label><input v-if="f.type==='checkbox'" :id="'fin-'+f.key" v-model="form[f.key]" type="checkbox"/><select v-else-if="selectType(f.type)" :id="'fin-'+f.key" v-model="form[f.key]" @change="f.key==='student_id'&&(form.allocations=[])"><option value="">Select / optional</option><template v-if="f.type.includes('|')"><option v-for="o in f.type.split('|')" :key="o" :value="o">{{ o.replaceAll('_',' ') }}</option></template><template v-else><option v-for="o in opts(f)" :key="o.id" :value="o.id">{{ o.label }}</option></template></select><input v-else-if="f.type==='file'" :id="'fin-'+f.key" type="file" accept=".pdf,.jpg,.jpeg,.png" @change="form[f.key]=($event.target as HTMLInputElement).files?.[0]??null"/><input v-else :id="'fin-'+f.key" v-model="form[f.key]" :type="f.type==='money'?'text':f.type" :inputmode="f.type==='money'?'decimal':undefined"/><p v-if="form.errors[f.key]" class="field-error">{{ form.errors[f.key] }}</p></div></div>
<section v-if="financePage==='payments'" class="finance-allocations"><h3>Invoice allocations</h3><p>Leave all unallocated for student credit. Allocation amounts cannot exceed invoice balances or the payment.</p><div v-for="(a,i) in form.allocations" :key="Number(i)" class="finance-allocation"><select v-model="a.invoice_id" :aria-label="`Allocation ${Number(i)+1} invoice`"><option value="">Choose invoice</option><option v-for="o in paymentInvoices" :key="o.id" :value="o.id">{{ o.label }}</option></select><input v-model="a.amount" inputmode="decimal" :aria-label="`Allocation ${Number(i)+1} amount`" placeholder="0.00"/><button type="button" class="delete-link" @click="form.allocations.splice(Number(i),1)">Remove</button></div><button type="button" class="secondary-button" :disabled="!form.student_id" @click="form.allocations.push({invoice_id:'',amount:''})">Add allocation</button></section>
<div v-if="Object.keys(form.errors).length" class="error-summary" role="alert"><p v-for="e in form.errors" :key="e">{{ e }}</p></div><div class="academic-form-footer"><button class="academic-button" :disabled="form.processing">{{ form.processing?'Saving…':'Save' }}</button><button type="button" class="secondary-button" @click="show=false">Cancel</button></div>
</form></section>

<form v-if="financePage!=='dashboard' && financePage!=='generate'" class="panel finance-filters no-print" @submit.prevent="apply"><div class="academic-form-grid"><div v-if="visibleFilters.includes('q')" class="form-field"><label for="finance-search">Search number / name</label><input id="finance-search" v-model="filter.q" type="search"/></div><div v-for="field in [{key:'academic_session_id',label:'Academic session',options:'sessions'},{key:'academic_class_id',label:'Class',options:'classes'},{key:'section_id',label:'Section',options:'sections'},{key:'student_id',label:'Student',options:'students'},{key:'fee_category_id',label:'Fee category',options:'categories'},{key:'expense_category_id',label:'Expense category',options:'expenseCategories'}].filter(f=>visibleFilters.includes(f.key))" :key="field.key" class="form-field"><label :for="'filter-'+field.key">{{ field.label }}</label><select :id="'filter-'+field.key" v-model="filter[field.key]"><option value="">All</option><option v-for="o in options[field.options]" :key="o.id" :value="o.id">{{ o.label }}</option></select></div><div v-for="key in ['from','to','due_from','due_to'].filter(k=>visibleFilters.includes(k))" :key="key" class="form-field"><label :for="'filter-'+key">{{ key.replaceAll('_',' ') }} {{ key.startsWith('due')?'':'(record date)' }}</label><input :id="'filter-'+key" v-model="filter[key]" type="date"/></div><div v-if="visibleFilters.includes('method')" class="form-field"><label for="filter-method">Payment method</label><select id="filter-method" v-model="filter.method"><option value="">All</option><option v-for="m in ['cash','bank_transfer','cheque','other']" :key="m">{{ m }}</option></select></div><div v-if="visibleFilters.includes('status')" class="form-field"><label for="filter-status">Invoice status</label><select id="filter-status" v-model="filter.status"><option value="">All</option><option v-for="s in ['draft','issued','partially_paid','paid','overdue','voided']" :key="s">{{ s }}</option></select></div><div v-if="financePage==='reports'" class="form-field"><label for="report-type">Report</label><select id="report-type" v-model="filter.report_type"><option v-for="s in ['invoices','outstanding','discounts','payments','daily','monthly','class','category','method','expenses','expense-categories','class-outstanding','student-outstanding','refunds']" :key="s">{{ s }}</option></select></div></div><div class="academic-actions"><button class="academic-button">Apply filters</button><Link class="secondary-button" :href="`${baseUrl}/${financePage}`">Clear</Link><a v-if="['reports','statements','defaulters'].includes(financePage)" class="secondary-button" :href="exportHref">Export CSV</a><button v-if="['reports','statements','defaulters'].includes(financePage)" type="button" class="secondary-button" @click="print">Print report</button></div><p v-for="e in ($page.props.errors as Record<string,string>)" :key="e" class="field-error">{{ e }}</p></form>

<template v-if="['reports','statements','defaulters'].includes(financePage)"><div class="finance-metrics"><article v-for="item in [{label:'Issued billings',key:'billed_minor'},{label:'Allocated net paid',key:'allocated_minor'},{label:'Outstanding',key:'outstanding_minor'},{label:'Overdue',key:'overdue_minor'}]" :key="item.key" class="panel"><small>{{ item.label }}</small><strong>{{ money(summary[item.key]) }}</strong></article></div><p class="finance-note">Invoice totals follow invoice issue dates. Payment reports follow payment dates. Aging is measured today on posted invoices. Future unpaid invoices are not overdue.</p><section class="panel finance-aging"><h2>Overdue aging</h2><div v-for="(v,k) in summary.aging" :key="k"><span>{{ k }} days</span><strong>{{ money(Number(v)) }}</strong></div></section></template>
<section v-if="['reports','statements'].includes(financePage)" class="panel"><div class="panel-heading"><h2>{{ financePage==='statements'?'Student statement':'Report results' }}</h2><span>First 100 detail rows; CSV exports all matches</span></div><div class="table-scroll"><table><thead><tr><th v-for="col in reportColumns" :key="col">{{ col.replaceAll('_',' ') }}</th></tr></thead><tbody><tr v-for="(row,i) in reportRows" :key="i"><td v-for="col in reportColumns" :key="col">{{ row[col] }}</td></tr></tbody></table></div><p v-if="!reportRows.length" class="academic-empty">{{ financePage==='statements'&&!filters.student_id?'Select a student to view their statement.':'No financial records match these filters.' }}</p></section>

<section v-if="rows" class="panel"><div class="table-scroll"><table><thead><tr><th>Record</th><th>Details</th><th>Amount / balance</th><th>Status</th><th class="no-print">Actions</th></tr></thead><tbody><tr v-for="row in rows.data" :key="row.id"><td><strong>{{ rowLabel(row) }}</strong><small>{{ rowDetail(row) }}</small></td><td>{{ row.paid_on??row.spent_on??row.refunded_on??row.period??row.effective_from??row.starts_on??row.created_at }}<small>{{ row.method??row.frequency??row.kind??'' }} {{ row.due_on?'Due '+row.due_on:'' }}</small><details v-if="financePage==='audit'"><summary>Audit changes</summary><pre>{{ JSON.stringify(row.changes,null,2) }}</pre><p>{{ row.actor_context.mode }} · authenticated: false</p></details><small v-if="row.credit_minor!==undefined">Available credit {{ money(row.credit_minor) }}</small><details v-if="row.allocations?.length"><summary>Invoice allocations</summary><p v-for="a in row.allocations" :key="a.invoice_id">Invoice #{{ a.invoice_id }} ? {{ money(a.amount_minor) }}</p></details><small v-if="row.reason">{{ row.reason }}</small></td><td>{{ row.amount_minor!==undefined?money(row.amount_minor):row.total_minor!==undefined?money(Number(row.total_minor)+Number(row.penalty_minor??0)):row.value?decimal(row.value)+(row.calculation==='percent'?'%':' '+metrics.currency):'—' }}<small v-if="row.outstanding_minor!==undefined">Paid {{ money(row.paid_minor) }} · Due {{ money(row.outstanding_minor) }}</small></td><td><span class="finance-status">{{ displayStatus(row) }}</span></td><td class="no-print"><div class="row-actions"><template v-if="financePage==='assignments'"><button @click="begin(row,'assignments',row.active?'deactivate':'activate')">{{ row.active?'Deactivate future billing':'Activate' }}</button></template><template v-if="editable"><button @click="open(row)">Edit</button><button class="delete-link" @click="remove(row)">Delete unused</button></template><template v-if="['invoices','defaulters'].includes(financePage)"><Link :href="`${baseUrl}/documents/invoice/${row.id}`">View / print</Link><button v-if="row.status==='draft'" @click="begin(row,'invoices','issue')">Issue</button><button v-if="row.status!=='voided'" @click="begin(row,'invoices','void')">Void</button><button v-if="row.status==='issued'" @click="begin(row,'invoices','post-penalty')">Preview late fee</button></template><template v-if="financePage==='payments'"><Link :href="`${baseUrl}/documents/receipt/${row.id}`">Receipt / reprint</Link><button v-if="row.status==='posted'" @click="begin(row,'payments','reverse')">Reverse</button><button v-if="row.status==='posted'" @click="begin(row,'payments','allocate')">Apply credit</button></template><template v-if="financePage==='refunds'&&row.status==='requested'"><button @click="begin(row,'refunds','post')">Post manual refund</button><button @click="begin(row,'refunds','reject')">Reject</button></template><a v-if="financePage==='expenses'&&row.attachment_path" :href="`${baseUrl}/expenses/${row.id}/attachment`">Private attachment</a></div></td></tr></tbody></table></div><p v-if="!rows.data.length" class="academic-empty">No records yet. Create a record or adjust the filters.</p><div class="academic-pagination no-print"><span>{{ rows.total }} records</span><nav aria-label="Pagination"><template v-for="(link,i) in rows.links" :key="i"><Link v-if="link.url" :href="link.url" :class="{active:link.active}" v-html="link.label"/><span v-else v-html="link.label"/></template></nav></div></section>

<section v-if="confirmation" id="finance-confirm" tabindex="-1" class="panel finance-confirm no-print" role="region" aria-label="Confirm financial action"><h2>Confirm {{ confirmation.action.replaceAll('-',' ') }} #{{ confirmation.id }}</h2><p>This action preserves the financial history and writes an audit event.</p><form @submit.prevent="perform"><div v-if="['void','reverse'].includes(confirmation.action)" class="form-field"><label for="action-reason">Reason</label><input id="action-reason" v-model="actionForm.reason"/></div><template v-if="confirmation.action==='allocate'"><div class="form-field"><label for="credit-invoice">Invoice</label><select id="credit-invoice" v-model="actionForm.invoice_id"><option value="">Select invoice</option><option v-for="o in options.invoices" :key="o.id" :value="o.id">{{ o.label }}</option></select></div><div class="form-field"><label for="credit-amount">Credit amount to allocate</label><input id="credit-amount" v-model="actionForm.amount" inputmode="decimal"/></div></template><template v-if="confirmation.action==='post-penalty'"><div class="form-field"><label for="penalty-policy">Policy</label><select id="penalty-policy" v-model="actionForm.policy_id" @change="preview=null"><option value="">Select policy</option><option v-for="p in options.policies" :key="p.id" :value="p.id">{{ p.label }}</option></select></div><button type="button" class="secondary-button" :disabled="previewBusy" @click="previewPenalty">{{ previewBusy?'Calculating…':'Preview calculated penalty' }}</button><p v-if="preview!==null">Penalty to post: <strong>{{ money(preview) }}</strong></p><p v-if="previewError" class="field-error">{{ previewError }}</p></template><div v-if="Object.keys(actionForm.errors).length" class="error-summary" role="alert"><p v-for="e in actionForm.errors" :key="e">{{ e }}</p></div><div class="academic-actions"><button class="academic-button" :disabled="actionForm.processing||(confirmation.action==='post-penalty'&&(!preview||previewBusy))">{{ actionForm.processing?'Recording…':'Confirm action' }}</button><button type="button" class="secondary-button" @click="confirmation=null">Cancel</button></div></form></section>
</DashboardLayout>
</template>
